package com.omnicore.keycloak;

import jakarta.ws.rs.core.MultivaluedMap;
import org.keycloak.http.HttpRequest;
import org.keycloak.models.ClientSessionContext;
import org.keycloak.models.KeycloakContext;
import org.keycloak.models.KeycloakSession;
import org.keycloak.models.ProtocolMapperModel;
import org.keycloak.models.RoleModel;
import org.keycloak.models.UserModel;
import org.keycloak.models.UserSessionModel;
import org.keycloak.protocol.oidc.mappers.AbstractOIDCProtocolMapper;
import org.keycloak.protocol.oidc.mappers.OIDCAccessTokenMapper;
import org.keycloak.protocol.oidc.mappers.OIDCIDTokenMapper;
import org.keycloak.protocol.oidc.mappers.UserInfoTokenMapper;
import org.keycloak.provider.ProviderConfigProperty;
import org.keycloak.representations.AccessToken;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.logging.Level;
import java.util.logging.Logger;

/**
 * OmniCore custom protocol mapper that resolves the requested org context
 * on every token mint and refresh.
 *
 * <h3>Flow</h3>
 * <ol>
 *   <li>Read {@code requested_org_id} from the OAuth2 token request's form params.</li>
 *   <li>If absent, keep the user's home {@code org_id} (already present from the
 *       {@code omnicore-org-id} attribute mapper) — no call to org-svc is made.</li>
 *   <li>If present, call {@code OrgVerifyClient.verify(userId, requestedOrgId)}.</li>
 *   <li>If {@code is_member=true}: overwrite {@code org_id} claim with the
 *       requested value and add {@code membership_role} claim.</li>
 *   <li>If {@code is_member=false}: throw a {@link ProtocolMapperException}
 *       so Keycloak returns {@code error=invalid_grant}.</li>
 *   <li>On any network / parse error: throw {@link ProtocolMapperException}
 *       (fail closed — never issue a token with an unverified org_id).</li>
 * </ol>
 *
 * <h3>Security invariants</h3>
 * <ul>
 *   <li>MUST NOT log token contents, claims body, refresh tokens, or org_id
 *       values at any log level.</li>
 *   <li>MUST fail closed — any error from org-svc results in token denial,
 *       never a stale claim.</li>
 * </ul>
 */
public class OmniCoreOrgMapper
        extends AbstractOIDCProtocolMapper
        implements OIDCAccessTokenMapper, OIDCIDTokenMapper, UserInfoTokenMapper {

    public static final String PROVIDER_ID = "omnicore-org-mapper";

    // Config property keys — set via Keycloak admin console or realm-export.json.
    static final String ORG_SVC_URL_KEY = "omnicore.org.svc.url";
    static final String TOKEN_PATH_KEY = "omnicore.org.svc.token.path";
    static final String TIMEOUT_MS_KEY = "omnicore.org.svc.timeout.ms";

    // Default values
    private static final String DEFAULT_ORG_SVC_URL = "https://org-svc:8443";
    private static final String DEFAULT_TOKEN_PATH = "/run/secrets/keycloak-org-mapper-token";
    private static final long DEFAULT_TIMEOUT_MS = 2000L;

    // Claim names written into the token — not logged.
    private static final String CLAIM_ORG_ID = "org_id";
    private static final String CLAIM_MEMBERSHIP_ROLE = "membership_role";

    // Form parameter name on the token request.
    private static final String PARAM_REQUESTED_ORG_ID = "requested_org_id";

    // User-session note that persists the active org across refresh grants.
    // cookie_to_bearer in shell-bff mints a fresh access token on every
    // request via a vanilla refresh grant — no requested_org_id form field —
    // so without this note the access token would silently snap back to
    // the user's home org_id on the very next request after a switch.
    static final String SESSION_NOTE_ACTIVE_ORG_ID = "omnicore_active_org_id";
    static final String SESSION_NOTE_ACTIVE_ROLE = "omnicore_active_role";

    private static final Logger LOG = Logger.getLogger(OmniCoreOrgMapper.class.getName());

    private static final List<ProviderConfigProperty> CONFIG_PROPERTIES = new ArrayList<>();

    static {
        ProviderConfigProperty urlProp = new ProviderConfigProperty();
        urlProp.setName(ORG_SVC_URL_KEY);
        urlProp.setLabel("org-svc base URL");
        urlProp.setType(ProviderConfigProperty.STRING_TYPE);
        urlProp.setDefaultValue(DEFAULT_ORG_SVC_URL);
        urlProp.setHelpText("Base URL of the org-svc internal REST shim (mTLS endpoint).");
        CONFIG_PROPERTIES.add(urlProp);

        ProviderConfigProperty tokenPathProp = new ProviderConfigProperty();
        tokenPathProp.setName(TOKEN_PATH_KEY);
        tokenPathProp.setLabel("Service-account token path");
        tokenPathProp.setType(ProviderConfigProperty.STRING_TYPE);
        tokenPathProp.setDefaultValue(DEFAULT_TOKEN_PATH);
        tokenPathProp.setHelpText(
                "Path to the mounted service-account Bearer token file "
                        + "(Kubernetes secret or Vault agent injection).");
        CONFIG_PROPERTIES.add(tokenPathProp);

        ProviderConfigProperty timeoutProp = new ProviderConfigProperty();
        timeoutProp.setName(TIMEOUT_MS_KEY);
        timeoutProp.setLabel("Request timeout (ms)");
        timeoutProp.setType(ProviderConfigProperty.STRING_TYPE);
        timeoutProp.setDefaultValue(String.valueOf(DEFAULT_TIMEOUT_MS));
        timeoutProp.setHelpText("HTTP timeout for the org-svc verify-membership call.");
        CONFIG_PROPERTIES.add(timeoutProp);
    }

    @Override
    public String getId() {
        return PROVIDER_ID;
    }

    @Override
    public String getDisplayType() {
        return "OmniCore Org Membership Mapper";
    }

    @Override
    public String getDisplayCategory() {
        return TOKEN_MAPPER_CATEGORY;
    }

    @Override
    public String getHelpText() {
        return "Resolves requested_org_id against org-svc VerifyMembership and sets "
                + "org_id + membership_role claims. Fails closed on any error.";
    }

    /**
     * Keycloak runs protocol mappers in ascending priority order — higher
     * number = later. The standard {@code oidc-usermodel-attribute-mapper}
     * used by {@code omnicore-org-id} runs with the framework default
     * (effectively 0), which means it writes the home {@code org_id} claim
     * AFTER our switch-aware logic, silently undoing every workspace switch.
     *
     * Pinning ourselves to {@link Integer#MAX_VALUE} guarantees we run last
     * and our {@code org_id}/{@code membership_role} writes survive any
     * other mapper that touches the same claims.
     */
    @Override
    public int getPriority() {
        return Integer.MAX_VALUE;
    }

    @Override
    public List<ProviderConfigProperty> getConfigProperties() {
        return CONFIG_PROPERTIES;
    }

    /**
     * Called by Keycloak on every access-token mint (including refresh grants).
     *
     * <p>The session + clientSession contexts give access to the token request
     * form parameters via the session notes that Keycloak has already extracted,
     * or directly from the request. Keycloak stores the raw grant form params
     * as session notes keyed by parameter name during the grant phase.
     *
     * <p>SECURITY: do not log userId, requestedOrgId, or any claim value.
     */
    // Realm role that grants implicit access to every tenant — the same
    // role gate used by org-svc ListAsAdmin, shell-bff buildAdminOrgs, etc.
    private static final String ADMIN_REALM_ROLE = "admin";

    @Override
    public AccessToken transformAccessToken(
            AccessToken token,
            ProtocolMapperModel mappingModel,
            KeycloakSession session,
            UserSessionModel userSession,
            ClientSessionContext clientSessionCtx) {

        // requested_org_id arrives only on the explicit switch request from
        // shell-bff. Plain refresh grants (cookie_to_bearer) do NOT carry it.
        // To keep the chosen org sticky across those refreshes, we persist
        // the last switch in a user-session note and consult that note on
        // every subsequent token mint.
        String requestedOrgId = resolveRequestedOrgId(session, clientSessionCtx);
        boolean fromForm = requestedOrgId != null && !requestedOrgId.isBlank();

        String activeOrgId = fromForm
                ? requestedOrgId
                : readSessionNote(userSession, SESSION_NOTE_ACTIVE_ORG_ID);

        if (activeOrgId == null || activeOrgId.isBlank()) {
            // No switch ever requested in this SSO session — leave the
            // home org_id claim (set by omnicore-org-id attribute mapper) alone.
            return token;
        }

        // Platform admins (realm role "admin") have implicit access to every
        // tenant — bypass the VerifyMembership call so they can scope into any
        // workspace without an explicit org.memberships row. Matches the
        // admin-bypass pattern used across org-svc and the BFFs.
        //
        // We consult the UserModel directly (not token.realmAccess) because
        // Keycloak's realm-role mapper may run AFTER ours; token.realmAccess
        // can be null at this point even for admin users. UserModel reflects
        // the persisted role assignment regardless of mapper order.
        if (hasAdminRealmRole(token, userSession)) {
            token.getOtherClaims().put(CLAIM_ORG_ID, activeOrgId);
            token.getOtherClaims().put(CLAIM_MEMBERSHIP_ROLE, ADMIN_REALM_ROLE);
            // Persist on first explicit switch only; replay-from-note doesn't
            // need to rewrite the same value every refresh.
            if (fromForm) {
                writeSessionNote(userSession, SESSION_NOTE_ACTIVE_ORG_ID, activeOrgId);
                writeSessionNote(userSession, SESSION_NOTE_ACTIVE_ROLE, ADMIN_REALM_ROLE);
            }
            return token;
        }

        // Non-admin path — must verify membership on every explicit switch.
        // On replay-from-note we trust the previously persisted membership
        // (it was already verified when first written; revoke flows clear
        // the session) and use the stored role to avoid re-hitting org-svc.
        String role;
        if (fromForm) {
            String userId = token.getSubject();
            OrgVerifyClient client = buildClient(mappingModel);
            OrgVerifyClient.VerifyResult result;
            try {
                result = client.verify(userId, activeOrgId);
            } catch (OrgVerifyClient.OrgVerifyException e) {
                LOG.log(Level.WARNING, "org-svc verify-membership call failed; denying token", e);
                throw new ProtocolMapperException("org membership verification failed");
            }
            if (!result.isMember) {
                LOG.log(Level.INFO, "org membership not confirmed for requested org; denying token");
                throw new ProtocolMapperException("user is not a member of the requested org");
            }
            role = result.membershipRole;
            writeSessionNote(userSession, SESSION_NOTE_ACTIVE_ORG_ID, activeOrgId);
            writeSessionNote(userSession, SESSION_NOTE_ACTIVE_ROLE, role);
        } else {
            role = readSessionNote(userSession, SESSION_NOTE_ACTIVE_ROLE);
            if (role == null) {
                role = "";
            }
        }

        token.getOtherClaims().put(CLAIM_ORG_ID, activeOrgId);
        token.getOtherClaims().put(CLAIM_MEMBERSHIP_ROLE, role);
        return token;
    }

    private static String readSessionNote(UserSessionModel userSession, String key) {
        if (userSession == null) {
            return null;
        }
        return userSession.getNote(key);
    }

    private static void writeSessionNote(
            UserSessionModel userSession, String key, String value) {
        if (userSession == null || value == null) {
            return;
        }
        userSession.setNote(key, value);
    }

    /**
     * Resolves the requested_org_id from either source it can arrive on:
     *
     * <ol>
     *   <li>The {@link ClientSessionContext} attribute — populated by tests
     *       and any future Keycloak authenticator that copies the form
     *       parameter into the session.</li>
     *   <li>The token-endpoint POST form parameters — the real path for a
     *       browser-initiated workspace switch, since Keycloak does not
     *       auto-copy custom grant form fields onto the client session.</li>
     * </ol>
     *
     * Returns {@code null} when neither source carries the value.
     */
    String resolveRequestedOrgId(
            KeycloakSession session, ClientSessionContext clientSessionCtx) {
        String fromCtx =
                clientSessionCtx.getAttribute(PARAM_REQUESTED_ORG_ID, String.class);
        if (fromCtx != null && !fromCtx.isBlank()) {
            return fromCtx;
        }

        if (session == null) {
            return null;
        }
        KeycloakContext ctx = session.getContext();
        if (ctx == null) {
            return null;
        }
        HttpRequest httpRequest = ctx.getHttpRequest();
        if (httpRequest == null) {
            return null;
        }
        MultivaluedMap<String, String> form = httpRequest.getDecodedFormParameters();
        if (form == null) {
            return null;
        }
        return form.getFirst(PARAM_REQUESTED_ORG_ID);
    }

    /**
     * Reports whether the calling user holds the platform-admin realm role.
     *
     * Consults {@code AccessToken.realmAccess.roles} first — if Keycloak's
     * realm-role mapper has already run, the answer is in the token. If
     * that side is empty (mapper order varies across grant types), falls
     * back to {@link UserModel#hasRole(RoleModel)} against the user-session
     * model so the bypass is deterministic regardless of mapper order.
     */
    static boolean hasAdminRealmRole(AccessToken token, UserSessionModel userSession) {
        AccessToken.Access realmAccess = token.getRealmAccess();
        if (realmAccess != null) {
            Set<String> roles = realmAccess.getRoles();
            if (roles != null && roles.contains(ADMIN_REALM_ROLE)) {
                return true;
            }
        }
        if (userSession == null) {
            return false;
        }
        UserModel user = userSession.getUser();
        if (user == null) {
            return false;
        }
        return user.getRealmRoleMappingsStream()
                .map(RoleModel::getName)
                .anyMatch(ADMIN_REALM_ROLE::equals);
    }

    /**
     * Builds an {@link OrgVerifyClient} from the mapper's config properties.
     * A new client is created per invocation — HttpClient is lightweight to
     * construct and this avoids holding stale connections across Keycloak
     * worker threads.
     */
    OrgVerifyClient buildClient(ProtocolMapperModel model) {
        String url = getConfigValue(model, ORG_SVC_URL_KEY, DEFAULT_ORG_SVC_URL);
        String tokenPath = getConfigValue(model, TOKEN_PATH_KEY, DEFAULT_TOKEN_PATH);
        long timeoutMs = parseLong(
                getConfigValue(model, TIMEOUT_MS_KEY, String.valueOf(DEFAULT_TIMEOUT_MS)),
                DEFAULT_TIMEOUT_MS);

        OrgVerifyClient.TokenSupplier tokenSupplier = () -> readTokenFile(tokenPath);
        return new OrgVerifyClient(url, tokenSupplier, timeoutMs);
    }

    /**
     * Reads the service-account token from a mounted file.
     * MUST NOT log file contents.
     */
    static String readTokenFile(String path) throws IOException {
        return Files.readString(Path.of(path)).strip();
    }

    private static String getConfigValue(
            ProtocolMapperModel model, String key, String defaultValue) {
        if (model == null || model.getConfig() == null) {
            return defaultValue;
        }
        String v = model.getConfig().get(key);
        return (v != null && !v.isBlank()) ? v : defaultValue;
    }

    private static long parseLong(String s, long fallback) {
        try {
            return Long.parseLong(s.strip());
        } catch (NumberFormatException e) {
            return fallback;
        }
    }

    /**
     * Unchecked wrapper so the mapper can signal token denial through
     * Keycloak's mapper pipeline, which does not declare a checked exception.
     */
    static final class ProtocolMapperException extends RuntimeException {
        ProtocolMapperException(String message) {
            super(message);
        }
    }
}


