package com.omnicore.keycloak;

import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;

/**
 * Thin HTTP client that calls the org-svc internal REST shim.
 *
 * <p>POST /internal/verify-membership
 * Request:  {"user_id": "<uuid>", "org_id": "<uuid>"}
 * Response: {"is_member": bool, "membership_role": "<string>"}
 *
 * <p>Authentication: a Bearer token is obtained from the configured
 * service-account token path (Kubernetes-style mounted secret or Vault
 * agent injection). The token carries azp=keycloak-org-mapper and
 * aud=org-svc, satisfying the shim's JWT gate.
 *
 * <p>SECURITY: this class MUST NOT log the token, request body, or
 * response body at any level.
 */
public class OrgVerifyClient {

    private final String baseUrl;
    private final TokenSupplier tokenSupplier;
    private final HttpClient httpClient;

    /**
     * Constructs a client that calls {@code baseUrl/internal/verify-membership}.
     *
     * @param baseUrl       base URL of org-svc (e.g. https://org-svc:8443), no trailing slash
     * @param tokenSupplier supplier of Bearer tokens for the request
     * @param timeoutMs     request timeout in milliseconds
     */
    public OrgVerifyClient(String baseUrl, TokenSupplier tokenSupplier, long timeoutMs) {
        this.baseUrl = baseUrl;
        this.tokenSupplier = tokenSupplier;
        this.httpClient = HttpClient.newBuilder()
                .connectTimeout(Duration.ofMillis(timeoutMs))
                .build();
    }

    /**
     * Verifies whether {@code userId} holds an active membership in {@code orgId}.
     *
     * @param userId UUID string of the user (Keycloak subject)
     * @param orgId  UUID string of the requested org
     * @return verification result containing membership status and role
     * @throws OrgVerifyException on any network error, non-200 response, or parse failure
     */
    public VerifyResult verify(String userId, String orgId) throws OrgVerifyException {
        String token;
        try {
            token = tokenSupplier.get();
        } catch (IOException e) {
            throw new OrgVerifyException("failed to obtain service-account token", e);
        }

        String requestBody = buildRequestBody(userId, orgId);
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(baseUrl + "/internal/verify-membership"))
                .header("Content-Type", "application/json")
                .header("Authorization", "Bearer " + token)
                .POST(HttpRequest.BodyPublishers.ofString(requestBody))
                .build();

        HttpResponse<String> response;
        try {
            response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
        } catch (IOException | InterruptedException e) {
            if (e instanceof InterruptedException) {
                Thread.currentThread().interrupt();
            }
            throw new OrgVerifyException("network error calling org-svc verify-membership", e);
        }

        if (response.statusCode() != 200) {
            // Do not include response body in the exception — it may contain sensitive data.
            throw new OrgVerifyException(
                    "org-svc verify-membership returned HTTP " + response.statusCode());
        }

        return parseResponse(response.body());
    }

    /**
     * Builds the JSON request body without exposing the values in any log statement.
     * Simple string concatenation is safe here — userId and orgId are UUID strings
     * validated upstream; no injection risk.
     */
    private static String buildRequestBody(String userId, String orgId) {
        return "{\"user_id\":\"" + userId + "\",\"org_id\":\"" + orgId + "\"}";
    }

    /**
     * Parses the JSON response body into a {@link VerifyResult}.
     * Uses manual parsing to avoid pulling in a JSON library dependency.
     * The response shape is fixed: {"is_member":bool,"membership_role":"<string>"}.
     */
    static VerifyResult parseResponse(String body) throws OrgVerifyException {
        if (body == null || body.isBlank()) {
            throw new OrgVerifyException("empty response body from org-svc");
        }
        boolean isMember = extractBoolField(body, "is_member");
        String role = extractStringField(body, "membership_role");
        return new VerifyResult(isMember, role == null ? "" : role);
    }

    private static boolean extractBoolField(String json, String fieldName) throws OrgVerifyException {
        String key = "\"" + fieldName + "\"";
        int keyIdx = json.indexOf(key);
        if (keyIdx < 0) {
            throw new OrgVerifyException("missing field '" + fieldName + "' in response");
        }
        int colonIdx = json.indexOf(':', keyIdx + key.length());
        if (colonIdx < 0) {
            throw new OrgVerifyException("malformed field '" + fieldName + "' in response");
        }
        String remainder = json.substring(colonIdx + 1).stripLeading();
        if (remainder.startsWith("true")) {
            return true;
        }
        if (remainder.startsWith("false")) {
            return false;
        }
        throw new OrgVerifyException("non-boolean value for field '" + fieldName + "'");
    }

    private static String extractStringField(String json, String fieldName) {
        String key = "\"" + fieldName + "\"";
        int keyIdx = json.indexOf(key);
        if (keyIdx < 0) {
            return null;
        }
        int colonIdx = json.indexOf(':', keyIdx + key.length());
        if (colonIdx < 0) {
            return null;
        }
        String remainder = json.substring(colonIdx + 1).stripLeading();
        if (!remainder.startsWith("\"")) {
            return null;
        }
        int end = remainder.indexOf('"', 1);
        if (end < 0) {
            return null;
        }
        return remainder.substring(1, end);
    }

    /** Result of a membership verification call. */
    public static final class VerifyResult {
        public final boolean isMember;
        public final String membershipRole;

        public VerifyResult(boolean isMember, String membershipRole) {
            this.isMember = isMember;
            this.membershipRole = membershipRole;
        }
    }

    /** Checked exception thrown on any error from the verify RPC. */
    public static final class OrgVerifyException extends Exception {
        public OrgVerifyException(String message) {
            super(message);
        }

        public OrgVerifyException(String message, Throwable cause) {
            super(message, cause);
        }
    }

    /**
     * Functional interface for supplying service-account Bearer tokens.
     * Implementations read from a mounted secret file (Kubernetes/Vault
     * agent pattern).
     */
    @FunctionalInterface
    public interface TokenSupplier {
        String get() throws IOException;
    }
}



