package com.omnicore.keycloak;

import jakarta.ws.rs.core.MultivaluedMap;
import org.keycloak.http.HttpRequest;
import org.keycloak.models.ClientSessionContext;
import org.keycloak.models.KeycloakContext;
import org.keycloak.models.KeycloakSession;
import org.keycloak.models.ProtocolMapperModel;
import org.keycloak.models.RoleModel;
import org.keycloak.models.UserModel;
import org.keycloak.models.UserSessionModel;
import org.keycloak.protocol.oidc.mappers.AbstractOIDCProtocolMapper;
import org.keycloak.protocol.oidc.mappers.OIDCAccessTokenMapper;
import org.keycloak.protocol.oidc.mappers.OIDCIDTokenMapper;
import org.keycloak.protocol.oidc.mappers.UserInfoTokenMapper;
import org.keycloak.provider.ProviderConfigProperty;
import org.keycloak.representations.AccessToken;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.logging.Level;
import java.util.logging.Logger;

/**
 * OmniCore custom protocol mapper that resolves the requested org context
 * on every token mint and refresh.
 *
 * <h3>Flow</h3>
 * <ol>
 *   <li>Read {@code requested_org_id} from the OAuth2 token request's form params.</li>
 *   <li>If absent, keep the user's home {@code org_id} (already present from the
 *       {@code omnicore-org-id} attribute mapper) — no call to org-svc is made.</li>
 *   <li>If present, call {@code OrgVerifyClient.verify(userId, requestedOrgId)}.</li>
 *   <li>If {@code is_member=true}: overwrite {@code org_id} claim with the
 *       requested value and add {@code membership_role} claim.</li>
 *   <li>If {@code is_member=false}: throw a {@link ProtocolMapperException}
 *       so Keycloak returns {@code error=invalid_grant}.</li>
 *   <li>On any network / parse error: throw {@link ProtocolMapperException}
 *       (fail closed — never issue a token with an unverified org_id).</li>
 * </ol>
 *
 * <h3>Security invariants</h3>
 * <ul>
 *   <li>MUST NOT log token contents, claims body, refresh tokens, or org_id
 *       values at any log level.</li>
 *   <li>MUST fail closed — any error from org-svc results in token denial,
 *       never a stale claim.</li>
 * </ul>
 */
