    // Config property keys — set via Keycloak admin console or realm-export.json.
    static final String ORG_SVC_URL_KEY = "omnicore.org.svc.url";
    static final String TOKEN_PATH_KEY = "omnicore.org.svc.token.path";
    static final String TIMEOUT_MS_KEY = "omnicore.org.svc.timeout.ms";

