        tokenPathProp.setName(TOKEN_PATH_KEY);
        tokenPathProp.setLabel("Service-account token path");
        tokenPathProp.setType(ProviderConfigProperty.STRING_TYPE);
        tokenPathProp.setDefaultValue(DEFAULT_TOKEN_PATH);
        tokenPathProp.setHelpText(
                "Path to the mounted service-account Bearer token file "
                        + "(Kubernetes secret or Vault agent injection).");
