    @Override
    public String getDisplayCategory() {
        return TOKEN_MAPPER_CATEGORY;
    }

    @Override
    public String getHelpText() {
        return "Resolves requested_org_id against org-svc VerifyMembership and sets "
                + "org_id + membership_role claims. Fails closed on any error.";
