    // Realm role that grants implicit access to every tenant — the same
    // role gate used by org-svc ListAsAdmin, shell-bff buildAdminOrgs, etc.
    private static final String ADMIN_REALM_ROLE = "admin";

    @Override
    public AccessToken transformAccessToken(
            AccessToken token,
