            ClientSessionContext clientSessionCtx) {

        // requested_org_id arrives only on the explicit switch request from
        // shell-bff. Plain refresh grants (cookie_to_bearer) do NOT carry it.
        // To keep the chosen org sticky across those refreshes, we persist
        // the last switch in a user-session note and consult that note on
        // every subsequent token mint.
        String requestedOrgId = resolveRequestedOrgId(session, clientSessionCtx);
        boolean fromForm = requestedOrgId != null && !requestedOrgId.isBlank();

        String activeOrgId = fromForm
                ? requestedOrgId
                : readSessionNote(userSession, SESSION_NOTE_ACTIVE_ORG_ID);

        if (activeOrgId == null || activeOrgId.isBlank()) {
            // No switch ever requested in this SSO session — leave the
            // home org_id claim (set by omnicore-org-id attribute mapper) alone.
            return token;
        }

