        // tenant — bypass the VerifyMembership call so they can scope into any
        // workspace without an explicit org.memberships row. Matches the
        // admin-bypass pattern used across org-svc and the BFFs.
        //
        // We consult the UserModel directly (not token.realmAccess) because
        // Keycloak's realm-role mapper may run AFTER ours; token.realmAccess
        // can be null at this point even for admin users. UserModel reflects
        // the persisted role assignment regardless of mapper order.
        if (hasAdminRealmRole(token, userSession)) {
            token.getOtherClaims().put(CLAIM_ORG_ID, activeOrgId);
            token.getOtherClaims().put(CLAIM_MEMBERSHIP_ROLE, ADMIN_REALM_ROLE);
            // Persist on first explicit switch only; replay-from-note doesn't
            // need to rewrite the same value every refresh.
            if (fromForm) {
                writeSessionNote(userSession, SESSION_NOTE_ACTIVE_ORG_ID, activeOrgId);
                writeSessionNote(userSession, SESSION_NOTE_ACTIVE_ROLE, ADMIN_REALM_ROLE);
            }
            return token;
        }

        // Non-admin path — must verify membership on every explicit switch.
        // On replay-from-note we trust the previously persisted membership
        // (it was already verified when first written; revoke flows clear
        // the session) and use the stored role to avoid re-hitting org-svc.
        String role;
        if (fromForm) {
            String userId = token.getSubject();
            OrgVerifyClient client = buildClient(mappingModel);
            OrgVerifyClient.VerifyResult result;
            try {
                result = client.verify(userId, activeOrgId);
            } catch (OrgVerifyClient.OrgVerifyException e) {
                LOG.log(Level.WARNING, "org-svc verify-membership call failed; denying token", e);
                throw new ProtocolMapperException("org membership verification failed");
            }
            if (!result.isMember) {
                LOG.log(Level.INFO, "org membership not confirmed for requested org; denying token");
                throw new ProtocolMapperException("user is not a member of the requested org");
            }
            role = result.membershipRole;
            writeSessionNote(userSession, SESSION_NOTE_ACTIVE_ORG_ID, activeOrgId);
            writeSessionNote(userSession, SESSION_NOTE_ACTIVE_ROLE, role);
        } else {
            role = readSessionNote(userSession, SESSION_NOTE_ACTIVE_ROLE);
            if (role == null) {
                role = "";
            }
        }

        token.getOtherClaims().put(CLAIM_ORG_ID, activeOrgId);
        token.getOtherClaims().put(CLAIM_MEMBERSHIP_ROLE, role);
        return token;
    }

    private static String readSessionNote(UserSessionModel userSession, String key) {
        if (userSession == null) {
            return null;
        }
        return userSession.getNote(key);
    }

    private static void writeSessionNote(
            UserSessionModel userSession, String key, String value) {
        if (userSession == null || value == null) {
            return;
        }
        userSession.setNote(key, value);
    }

    /**
     * Resolves the requested_org_id from either source it can arrive on:
     *
     * <ol>
     *   <li>The {@link ClientSessionContext} attribute — populated by tests
     *       and any future Keycloak authenticator that copies the form
     *       parameter into the session.</li>
     *   <li>The token-endpoint POST form parameters — the real path for a
     *       browser-initiated workspace switch, since Keycloak does not
     *       auto-copy custom grant form fields onto the client session.</li>
     * </ol>
     *
     * Returns {@code null} when neither source carries the value.
     */
    String resolveRequestedOrgId(
            KeycloakSession session, ClientSessionContext clientSessionCtx) {
        String fromCtx =
                clientSessionCtx.getAttribute(PARAM_REQUESTED_ORG_ID, String.class);
        if (fromCtx != null && !fromCtx.isBlank()) {
            return fromCtx;
        }

        if (session == null) {
            return null;
        }
        KeycloakContext ctx = session.getContext();
        if (ctx == null) {
            return null;
        }
        HttpRequest httpRequest = ctx.getHttpRequest();
        if (httpRequest == null) {
            return null;
        }
        MultivaluedMap<String, String> form = httpRequest.getDecodedFormParameters();
        if (form == null) {
            return null;
        }
        return form.getFirst(PARAM_REQUESTED_ORG_ID);
    }

    /**
     * Reports whether the calling user holds the platform-admin realm role.
     *
     * Consults {@code AccessToken.realmAccess.roles} first — if Keycloak's
     * realm-role mapper has already run, the answer is in the token. If
     * that side is empty (mapper order varies across grant types), falls
     * back to {@link UserModel#hasRole(RoleModel)} against the user-session
     * model so the bypass is deterministic regardless of mapper order.
     */
    static boolean hasAdminRealmRole(AccessToken token, UserSessionModel userSession) {
        AccessToken.Access realmAccess = token.getRealmAccess();
        if (realmAccess != null) {
            Set<String> roles = realmAccess.getRoles();
            if (roles != null && roles.contains(ADMIN_REALM_ROLE)) {
                return true;
            }
        }
        if (userSession == null) {
            return false;
        }
        UserModel user = userSession.getUser();
        if (user == null) {
            return false;
        }
        return user.getRealmRoleMappingsStream()
                .map(RoleModel::getName)
                .anyMatch(ADMIN_REALM_ROLE::equals);
    }

    /**
     * Builds an {@link OrgVerifyClient} from the mapper's config properties.
     * A new client is created per invocation — HttpClient is lightweight to
     * construct and this avoids holding stale connections across Keycloak
     * worker threads.
     */
    OrgVerifyClient buildClient(ProtocolMapperModel model) {
        String url = getConfigValue(model, ORG_SVC_URL_KEY, DEFAULT_ORG_SVC_URL);
        String tokenPath = getConfigValue(model, TOKEN_PATH_KEY, DEFAULT_TOKEN_PATH);
        long timeoutMs = parseLong(
                getConfigValue(model, TIMEOUT_MS_KEY, String.valueOf(DEFAULT_TIMEOUT_MS)),
                DEFAULT_TIMEOUT_MS);

        OrgVerifyClient.TokenSupplier tokenSupplier = () -> readTokenFile(tokenPath);
        return new OrgVerifyClient(url, tokenSupplier, timeoutMs);
    }

    /**
     * Reads the service-account token from a mounted file.
     * MUST NOT log file contents.
     */
    static String readTokenFile(String path) throws IOException {
        return Files.readString(Path.of(path)).strip();
    }

    private static String getConfigValue(
            ProtocolMapperModel model, String key, String defaultValue) {
        if (model == null || model.getConfig() == null) {
            return defaultValue;
        }
        String v = model.getConfig().get(key);
        return (v != null && !v.isBlank()) ? v : defaultValue;
    }

    private static long parseLong(String s, long fallback) {
        try {
            return Long.parseLong(s.strip());
        } catch (NumberFormatException e) {
            return fallback;
        }
    }

    /**
     * Unchecked wrapper so the mapper can signal token denial through
     * Keycloak's mapper pipeline, which does not declare a checked exception.
     */
    static final class ProtocolMapperException extends RuntimeException {
        ProtocolMapperException(String message) {
            super(message);
        }
    }
}


